style.css:
@-moz-document domain("powerpoint.cloud.microsoft.com") {
/* --------- CORES BÁSICAS --------- */
  body, html {
    background-color: #f3f3f3 !important;
    color: #222 !important;
    font-family: "Segoe UI", Arial, sans-serif !important;
  }

  /* --------- BARRA SUPERIOR (LARANJA CLÁSSICA) --------- */
  header, .TopBar, .AppHeader, .ms-TopBar {
    background-color: #d24726 !important;  /* Laranja clássico do Office 2013 */
    color: white !important;
    border: none !important;
    box-shadow: none !important;
  }

  /* --------- BOTÕES E ÍCONES --------- */
  button, .Button, .CommandBarButton, .ms-Button {
    border-radius: 0 !important;
    background-color: #f4f4f4 !important;
    color: #222 !important;
    border: 1px solid #d0d0d0 !important;
    box-shadow: none !important;
    font-weight: 500 !important;
  }

  button:hover, .Button:hover, .CommandBarButton:hover, .ms-Button:hover {
    background-color: #e5e5e5 !important;
    border-color: #c0c0c0 !important;
  }

  /* --------- REMOVER MODERNISMOS --------- */
  * {
    border-radius: 0 !important;
    box-shadow: none !important;
    backdrop-filter: none !important;
  }

  /* --------- PAINEL LATERAL --------- */
  .Sidebar, .TaskPane, .ms-Panel {
    background-color: #ffffff !important;
    border-left: 1px solid #ccc !important;
  }

  /* --------- ÁREA DE EDIÇÃO --------- */
  .CanvasContainer, .EditorSurface {
    background-color: #ffffff !important;
    border: 1px solid #ccc !important;
  }

  /* --------- BARRA DE FERRAMENTAS --------- */
  .Ribbon, .RibbonBar, .CommandBar {
    background-color: #ebebeb !important;
    border-bottom: 1px solid #c9c9c9 !important;
  }

  /* --------- SELEÇÃO DE SLIDES --------- */
  .ThumbnailPane, .SlideList {
    background-color: #fafafa !important;
  }

  /* --------- SCROLLBAR ESTILO ANTIGO --------- */
  ::-webkit-scrollbar {
    width: 10px !important;
    height: 10px !important;
  }
  ::-webkit-scrollbar-track {
    background: #f3f3f3 !important;
  }
  ::-webkit-scrollbar-thumb {
    background-color: #b3b3b3 !important;
    border: 2px solid #f3f3f3 !important;
  }
}
